"""Metadata only (no image downloads): license, author, size of candidate photos on Wikimedia Commons."""
import json, re, sys, time, urllib.parse, urllib.request, urllib.error
UA = {"User-Agent": "ai-tree-video/0.1 (personal non-commercial explainer video)"}
API = "https://commons.wikimedia.org/w/api.php"


def get(url, tries=6, head=False):
    for k in range(tries):
        try:
            req = urllib.request.Request(url, headers=UA, method="HEAD" if head else "GET")
            with urllib.request.urlopen(req, timeout=60) as r:
                return r.headers if head else r.read()
        except urllib.error.HTTPError as e:
            if e.code in (429, 503):
                wait = int(e.headers.get("Retry-After") or 0) or 15 * (k + 1)
                print(f"HTTP {e.code}, waiting {wait}s", file=sys.stderr, flush=True); time.sleep(wait); continue
            raise
    raise SystemExit("gave up: " + url)


